            "text": "자녀를 사랑하는 것은 귀한 일이다. 그러나 자녀의 성공이 곧 부모 자신의 성공이 되면, 자녀는 부모의 영혼의 목마름을 채워야 하는 무거운 짐을 지게 된다."
